    hours, minutes = time_str.split(':')
    hours = int(hours)
    minutes = int(minutes)

    if hours >= 24 or hours < 0:
        raise ValueError(f"Invalid hour: {hours}")

    if minutes >= 60 or minutes < 0:
        raise ValueError(f"Invalid minute: {minutes}")

    return hours * 60 + minutes

